def test_wildfire_feature_general(client):
    response = client.post("/api/wildfire/predict", json={"brightness": 330})
    assert response.status_code == 200


def test_wildfire_negative_brightness_rejected(client):
    response = client.post("/api/wildfire/predict", json={"brightness": -10})
    assert response.status_code == 422
